/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg data = 0;
  wire match, not_match;

  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data), .match(match), .not_match(not_match));

  always #5 clk = ~clk;

  task send_bit(input reg b);
    begin
      data = b;
      #10;
      "'$display("t=%0t data=%0b pstate=%0d match=%0b not_match=%0b", $time, data, dut.pstate, match, not_match);
    end
  endtask

  initial begin
    $display("start");
    #2; rst_n = 0;
    #8; rst_n = 1;

    // matching group: 0 1 1 1 0 0
    send_bit(0); send_bit(1); send_bit(1); send_bit(1); send_bit(0); send_bit(0);
    // one extra bit to observe pulse timing
    send_bit(1);

    // failing group: first bit wrong, then arbitrary 5 bits
    send_bit(1); send_bit(0); send_bit(0); send_bit(0); send_bit(0); send_bit(0);
    send_bit(0);

    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

