@@
-always @(posedge clk or negedge rst_n) begin
-	if ("'!rst_n) begin
-		match <= 1'"'b0;
-		not_match <= 1'b0;
-	end
-	else if (pstate == s6) begin
-		match <= 1'b1;
-		not_match <= 1'b0;
-	end
-	else if (pstate == sf6) begin
-		match <= 1'b0;
-		not_match <= 1'b1;
-	end
-	else begin
-		match <= 1'b0;
-		not_match <= 1'b0;
-	end
+always @(*) begin
+	match = 1'b0;
+	not_match = 1'b0;
+
+	if (rst_n) begin
+		case (pstate)
